// SMART DUE DILIGENCE TASK FINDER - robust like TaskEnhance
const tasks = $input.first().json.result || [];
console.log(`🔍 Checking ${tasks.length} tasks for Due Diligence processing`);

// Define all 20 sections in correct sequential order
const ALL_SECTIONS = [
  "Introduction & Engagement Context",
  "Methodology & Reliability Levels", 
  "Company Overview",
  "Business Model & Unit Economics",
  "Products & Technology",
  "Target Market & Competitive Set",
  "Financials",
  "Cash, Burn, Runway",
  "Revenue Quality & Client Cohorts",
  "Partnerships & Ecosystem",
  "Intellectual Property",
  "Legal & Regulatory",
  "Governance & Board Effectiveness",
  "Capital Structure & Dilution",
  "Risk Matrix & Mitigations",
  "Gaps, Uncertainties & Disclaimers",
  "Scenario Analysis",
  "Strategic Options",
  "Recommendations & Next Steps",
  "Source Map & Integrity Log"
];

// Find FIRST Due Diligence task that needs processing
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  console.log(`Task ${task.id}: title="${title}" desc_length=${description.trim().length}`);

  // Must be a Due Diligence task (contains company name after "Due Diligence:")
  if (!title.toLowerCase().includes('due diligence:')) {
    continue;
  }

  // Extract company name
  const companyName = title.replace(/due diligence:\s*/i, '').trim();

  // Must have company website in description
  if (!description.trim() || !description.includes('http')) {
    console.log(`❌ Task ${task.id} missing website - skipping`);
    continue;
  }

  // Skip if already completely done
  if (description.includes('🤖 COMPLETE DUE DILIGENCE REPORT GENERATED')) {
    console.log(`✅ Task ${task.id} already complete - skipping`);
    continue;
  }

  // Count approved sections
  const approvedMatches = description.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/g) || [];
  const approvedSections = approvedMatches.map(match => {
    const nameMatch = match.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/);
    return nameMatch ? nameMatch[1] : '';
  }).filter(name => name);

  console.log(`📊 Task ${task.id}: ${approvedSections.length}/${ALL_SECTIONS.length} sections complete`);

  // Find NEXT section to process (sequential order)
  let nextSection = null;
  let nextIndex = -1;

  for (let i = 0; i < ALL_SECTIONS.length; i++) {
    if (!approvedSections.includes(ALL_SECTIONS[i])) {
      nextSection = ALL_SECTIONS[i];
      nextIndex = i;
      break;
    }
  }

  // All sections done? Create final report
  if (!nextSection) {
    console.log(`🎉 All sections complete for ${companyName} - generating final report`);
    return {
      json: {
        task_id: task.id,
        company_name: companyName,
        title: title,
        description: description,
        project_id: task.project_id || 1,
        workflow_stage: "FINAL_REPORT",
        approved_sections: approvedSections,
        total_sections: ALL_SECTIONS.length,
        website_url: description.match(/https?:\/\/[^\s]+/)?.[0] || 'Not provided'
      }
    };
  }

  // Found FIRST task that needs processing
  console.log(`🎯 Processing section: ${nextSection} (${nextIndex + 1}/${ALL_SECTIONS.length})`);
  return {
    json: {
      task_id: task.id,
      company_name: companyName,
      title: title,
      description: description,
      project_id: task.project_id || 1,
      workflow_stage: "PROCESS_SECTION",
      current_section_name: nextSection,
      current_section_index: nextIndex,
      approved_sections: approvedSections,
      total_sections: ALL_SECTIONS.length,
      website_url: description.match(/https?:\/\/[^\s]+/)?.[0] || 'Not provided'
    }
  };
}

// No tasks found - end gracefully like TaskEnhance
console.log('ℹ️ No Due Diligence tasks need processing - workflow completed successfully');
throw new Error('No Due Diligence tasks need processing - workflow completed successfully');

// ROBUST DATA PREPARATION - like TaskEnhance error handling
const taskData = $('Find Due Diligence Task').first().json;
const attachments = $('Get PDF Attachments').first().json.result || [];

// Handle FinBERT data with robust error handling
let financialData = 'Financial analysis not available';
let finbertError = false;

try {
  const finbertResponse = $('FinBERT Financial Analysis').first();

  if (finbertResponse && finbertResponse.json) {
    const finbertResult = finbertResponse.json;

    if (finbertResult.results) {
      financialData = JSON.stringify(finbertResult.results, null, 2);
      console.log('✅ FinBERT analysis successful');
    } else if (finbertResult.analysis) {
      financialData = finbertResult.analysis;
      console.log('✅ FinBERT analysis successful (alternative format)');
    } else if (finbertResult.sentiment || finbertResult.score) {
      financialData = `Sentiment: ${finbertResult.sentiment || 'neutral'}, Score: ${finbertResult.score || 'N/A'}`;
      console.log('✅ FinBERT sentiment analysis successful');
    } else {
      finbertError = true;
      console.log('⚠️ FinBERT response format unexpected');
    }
  } else {
    finbertError = true;
    console.log('⚠️ FinBERT service unavailable');
  }
} catch (error) {
  finbertError = true;
  console.log(`⚠️ FinBERT error: ${error.message}`);
  financialData = `FinBERT service error: ${error.message}`;
}

// Section definitions with detailed scope
const SECTION_DESCRIPTIONS = {
  "Introduction & Engagement Context": "Context, objectives, and scope of the due diligence engagement",
  "Methodology & Reliability Levels": "Analytical approach, data sources, and reliability assessment methodology",
  "Company Overview": "Company history, leadership team, ownership structure, mission, and operational scale",
  "Business Model & Unit Economics": "Revenue streams, cost structure, pricing strategy, and unit economics analysis",
  "Products & Technology": "Product portfolio, technology stack, R&D capabilities, and competitive differentiation",
  "Target Market & Competitive Set": "Market segments, customer base, competitive landscape, and market positioning",
  "Financials": "Multi-year financial statements analysis, reconciliation, and recomputation",
  "Cash, Burn, Runway": "Cash position, burn rate analysis, and runway calculations",
  "Revenue Quality & Client Cohorts": "Revenue composition, client concentration, retention, and cohort analysis",
  "Partnerships & Ecosystem": "Strategic partnerships, ecosystem integration, and channel relationships",
  "Intellectual Property": "Patent portfolio, trademarks, copyrights, and IP strategy",
  "Legal & Regulatory": "Legal structure, compliance status, regulatory risks, and litigation",
  "Governance & Board Effectiveness": "Board composition, governance practices, and decision-making processes",
  "Capital Structure & Dilution": "Equity structure, debt analysis, and potential dilution scenarios",
  "Risk Matrix & Mitigations": "Key risk identification, assessment, and mitigation strategies",
  "Gaps, Uncertainties & Disclaimers": "Data gaps, analytical uncertainties, and disclosure disclaimers",
  "Scenario Analysis": "Multiple scenario modeling and sensitivity analysis",
  "Strategic Options": "Strategic alternatives and growth pathways for the company",
  "Recommendations & Next Steps": "Actionable recommendations and proposed next steps",
  "Source Map & Integrity Log": "Data sources mapping and integrity verification log"
};

const currentSection = taskData.current_section_name;
const sectionDescription = SECTION_DESCRIPTIONS[currentSection] || 'Section analysis';

console.log(`🎯 Setup complete for section: ${currentSection}`);
console.log(`📊 Progress: ${taskData.approved_sections.length}/${taskData.total_sections}`);
console.log(`💰 FinBERT status: ${finbertError ? 'ERROR' : 'SUCCESS'}`);
console.log(`📎 Attachments: ${attachments.length} files`);

return {
  json: {
    ...taskData,
    section_description: sectionDescription,
    attachments: attachments.map(a => a.name || 'unknown_file'),
    financial_data: financialData,
    finbert_available: !finbertError,
    knowledge_base: {
      website: taskData.website_url,
      pdfs: attachments.map(a => a.name || 'unknown_file'),
      financial_analysis: financialData,
      prior_sections: taskData.approved_sections,
      total_sources: attachments.length + 1 + (finbertError ? 0 : 1)
    }
  }
};

