=You are the MAKER agent in a Maker-Checker-Approver (MCA) workflow for Due Diligence reports.

🎯 TASK: Draft the "{{ $json.current_section_name }}" section

📋 COMPANY: {{ $json.company_name }}
📝 SECTION SCOPE: {{ $json.section_description }}
📊 PROGRESS: Section {{ $json.current_section_index + 1 }} of {{ $json.total_sections }}

🔍 KNOWLEDGE BASE AVAILABLE:
- 🌐 Company Website: {{ $json.website_url }}
- 📎 PDF Documents: {{ $json.attachments.join(', ') || 'None attached' }}
- 💰 Financial Analysis: {{ $json.finbert_available ? 'FinBERT analysis available' : 'FinBERT unavailable' }}
- 📚 Prior Approved Sections: {{ $json.approved_sections.join(', ') || 'None yet' }}
- 📈 Financial Data: {{ $json.financial_data.substring(0, 200) }}{{ $json.financial_data.length > 200 ? '...' : '' }}

📋 CRITICAL INSTRUCTIONS:
1. Create comprehensive, professional content for THIS SECTION ONLY
2. Use ONLY information from the Knowledge Base sources listed above
3. If specific data is missing, explicitly state: "Not available in provided materials"
4. Structure with clear headings and professional narrative
5. Include inline citations to specific sources (PDFs, website, financial analysis)
6. NO hallucination, simulation, mockups, or invented data
7. Focus on factual analysis appropriate for executive decision-making

✅ OUTPUT FORMAT - Respond ONLY with valid JSON:
{
  "section": "{{ $json.current_section_name }}",
  "content": "[Detailed section content with headings and professional structure]",
  "citations": ["source1", "source2", "financial_analysis"]
}

parameters.functionCode:
// MAKER RESPONSE PROCESSOR - robust like TaskEnhance
const sectionData = $('Prepare Section Data').first().json;
const makerResponse = $input.first().json.response;

console.log(`🤖 Processing Maker response for: ${sectionData.current_section_name}`);
console.log(`📄 Response length: ${makerResponse.length} characters`);

// Parse Maker content with robust error handling
let makerContent;
try {
  // Look for JSON in the response - like TaskEnhance
  const jsonMatch = makerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    makerContent = {
      section: parsed.section || sectionData.current_section_name,
      content: parsed.content || makerResponse,
      citations: parsed.citations || ['AI generated content']
    };
    console.log('✅ Maker JSON parsed successfully');
  } else {
    throw new Error('No JSON found in Maker response');
  }
} catch (error) {
  console.log(`⚠️ Maker JSON parsing failed: ${error.message}`);
  console.log('Using fallback content structure');

  // Create meaningful fallback - like TaskEnhance
  makerContent = {
    section: sectionData.current_section_name,
    content: `## ${sectionData.current_section_name}\n\n${makerResponse}\n\n*Note: This section was generated from AI response that could not be parsed as JSON.*`,
    citations: ['AI response', 'Knowledge Base']
  };
}

// Validate content quality
if (!makerContent.content || makerContent.content.trim().length < 50) {
  console.log('⚠️ Maker content too short, enhancing...');
  makerContent.content = `## ${sectionData.current_section_name}\n\n${sectionData.section_description}\n\nBased on available materials for ${sectionData.company_name}, this section requires further analysis. The following information has been compiled from the Knowledge Base:\n\n- Company Website: ${sectionData.website_url}\n- Available Documents: ${sectionData.attachments.join(', ') || 'None'}\n- Financial Analysis: ${sectionData.finbert_available ? 'Available' : 'Not available'}\n\n${makerResponse}\n\n*This analysis is based on available materials and may require additional information for completeness.*`;
}

console.log(`✅ Maker content prepared (${makerContent.content.length} chars)`);

return {
  json: {
    ...sectionData,
    maker_content: makerContent.content,
    maker_citations: makerContent.citations,
    maker_status: 'completed'
  }
};

