=You are the CHECKER agent in a Maker-Checker-Approver (MCA) workflow for Due Diligence reports.

🔍 TASK: Review the Maker's draft for accuracy and completeness

📋 SECTION: {{ $json.current_section_name }}
🏢 COMPANY: {{ $json.company_name }}
📊 PROGRESS: Section {{ $json.current_section_index + 1 }} of {{ $json.total_sections }}

🔍 KNOWLEDGE BASE FOR VALIDATION:
- 🌐 Website: {{ $json.website_url }}
- 📎 PDFs: {{ $json.attachments.join(', ') || 'None' }}
- 💰 Financial Data: {{ $json.finbert_available ? 'FinBERT analysis available' : 'FinBERT unavailable' }}
- 📚 Prior Sections: {{ $json.approved_sections.join(', ') || 'None' }}

📄 MAKER'S DRAFT TO REVIEW:
{{ $json.maker_content }}

🎯 VALIDATION CRITERIA:
1. ACCURACY: Is all content fully supported by the Knowledge Base?
2. NO HALLUCINATION: Are there any unsupported claims or invented data?
3. NO MOCK DATA: Are there placeholders, guesses, or fabricated numbers?
4. COMPLETENESS: Does it fully address the section scope ({{ $json.section_description }})?
5. CITATIONS: Are sources properly referenced and valid?
6. FACTUAL BASIS: Is everything grounded in provided materials?

❌ REJECT if any content is unsupported, invented, or incomplete
✅ APPROVE only if everything is accurate and complete

✅ OUTPUT FORMAT - Respond ONLY with valid JSON:
{
  "decision": "approve" OR "reject",
  "feedback": "If reject: specify exact issues and what needs to be fixed. If approve: confirm validation complete."
}

parameters.functionCode:
// CHECKER RESULT PROCESSOR - robust like TaskEnhance
const sectionData = $('Process Maker').first().json;
const checkerResponse = $('AI Checker').first().json.response;

console.log(`🔍 Processing Checker result for: ${sectionData.current_section_name}`);
console.log(`📄 Checker response length: ${checkerResponse.length} characters`);

// Parse Checker decision with robust error handling
let checkerDecision;
try {
  // Look for JSON in the response - like TaskEnhance
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    checkerDecision = {
      decision: (parsed.decision || 'approve').toLowerCase(),
      feedback: parsed.feedback || 'Checker review completed'
    };
    console.log('✅ Checker JSON parsed successfully');
  } else {
    throw new Error('No JSON found in Checker response');
  }
} catch (error) {
  console.log(`⚠️ Checker JSON parsing failed: ${error.message}`);
  console.log('Using fallback approval - content appears acceptable');

  // Default to approve if we can't parse - like TaskEnhance fallback
  checkerDecision = {
    decision: "approve",
    feedback: `Checker review completed. Original response: ${checkerResponse.substring(0, 200)}...`
  };
}

// Ensure decision is valid
if (!['approve', 'reject'].includes(checkerDecision.decision)) {
  console.log(`⚠️ Invalid checker decision: ${checkerDecision.decision}, defaulting to approve`);
  checkerDecision.decision = 'approve';
}

console.log(`🔍 Checker decision: ${checkerDecision.decision.toUpperCase()}`);
console.log(`💬 Checker feedback: ${checkerDecision.feedback.substring(0, 100)}...`);

return {
  json: {
    ...sectionData,
    checker_decision: checkerDecision.decision,
    checker_feedback: checkerDecision.feedback,
    checker_status: 'completed'
  }
};

