// FINAL REPORT GENERATOR - comprehensive PDF-ready report
const taskData = $input.first().json;
console.log(`📄 Generating final comprehensive report for ${taskData.company_name}`)

// Extract all approved sections from task description
const description = taskData.description || '';
const sectionRegex = /📋 \*\*(.*?)\*\* - ✅ APPROVED

([\s\S]*?)

---/g;
const sections = [];
let match;

while ((match = sectionRegex.exec(description)) !== null) {
  sections.push({
    name: match[1],
    content: match[2].trim()
  });
}

console.log(`📊 Found ${sections.length} approved sections to compile`);

// Build comprehensive executive-ready report
let report = `# 📊 COMPREHENSIVE DUE DILIGENCE REPORT

`;
report += `**Company:** ${taskData.company_name}
`;
report += `**Generated:** ${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}
`;
report += `**Sections Completed:** ${sections.length}/${taskData.total_sections}
`;
report += `**Website:** ${taskData.website_url}
`;
report += `**Process:** AI-Powered Maker-Checker-Approver (MCA) Workflow

`;
report += `---

`;

// Executive Summary
report += `## 📋 EXECUTIVE SUMMARY

`;
report += `This comprehensive Due Diligence Report for **${taskData.company_name}** has been compiled through our rigorous AI-powered Maker-Checker-Approver (MCA) process, ensuring the highest standards of accuracy, completeness, and business relevance.

`;
report += `**Key Report Highlights:**
`;
report += `- ${sections.length} sections completed and validated through triple-review process
`;
report += `- Content verified against Knowledge Base including PDFs, website, and financial analysis
`;
report += `- Each section approved by Maker → Checker → Approver workflow
`;
report += `- Ready for executive decision-making and board-level presentations

`;
report += `**Quality Assurance Process:**
`;
report += `1. **Maker**: AI-generated content from verified sources
`;
report += `2. **Checker**: Accuracy validation against Knowledge Base
`;
report += `3. **Approver**: Business relevance and executive readiness review

`;
report += `---

`;

// Table of Contents
report += `## 📑 TABLE OF CONTENTS

`;
sections.forEach((section, index) => {
  report += `${index + 1}. [${section.name}](#${section.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')})
`;
});
report += `
---

`;

// Add all approved sections
sections.forEach((section, index) => {
  report += `## ${index + 1}. ${section.name}

`;
  report += `${section.content}

`;
  report += `---

`;
});

// Process Documentation
report += `## 📋 PROCESS DOCUMENTATION

`;
report += `### MCA Workflow Details

`;
report += `**Maker Phase:**
- AI content generation using Mistral model
- Source validation against Knowledge Base
- Structured output with citations

`;
report += `**Checker Phase:**
- Accuracy verification against source materials
- Hallucination detection and prevention
- Completeness assessment

`;
report += `**Approver Phase:**
- Business relevance evaluation
- Executive readiness assessment
- Consistency verification

`;
report += `### Quality Metrics

`;
report += `- **Completion Rate:** ${sections.length}/${taskData.total_sections} (${Math.round(sections.length/taskData.total_sections*100)}%)
`;
report += `- **Validation Process:** Triple-reviewed (MCA)
`;
report += `- **Source Integration:** Website + PDFs + Financial Analysis
`;
report += `- **AI Model:** Mistral (Latest)
`;
report += `- **Generation Date:** ${new Date().toISOString()}

`;

// Disclaimers and Notes
report += `## ⚠️ DISCLAIMERS AND LIMITATIONS

`;
report += `**Data Sources:**
- Analysis based on publicly available information and provided materials
- Financial analysis includes AI-powered sentiment analysis where available
- All content has been triple-validated through MCA process

`;
report += `**Limitations:**
- Analysis limited to provided source materials
- AI-generated content subject to model limitations
- Recommendations require human expert review before implementation

`;
report += `**Next Steps:**
