report += `*Report generated by AI-Powered Due Diligence System v2.0*
`;
report += `*© ${new Date().getFullYear()} - Confidential and Proprietary*`;

return {
  json: {
    ...taskData,
    final_report_content: report,
    report_ready: true,
    sections_included: sections.length,
    report_length: report.length,
    generation_timestamp: new Date().toISOString()
